package com.mamtrex.hospital.department;
import com.mamtrex.hospital.audit.AuditService; import com.mamtrex.hospital.shared.NotFoundException; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/departments") public class DepartmentController { private final DepartmentRepository repo; private final AuditService audit; public DepartmentController(DepartmentRepository r,AuditService a){repo=r;audit=a;} public record Request(@jakarta.validation.constraints.NotBlank String code, @jakarta.validation.constraints.NotBlank String name, @jakarta.validation.constraints.NotBlank String specialty, @jakarta.validation.constraints.NotBlank String location){} @PostMapping public Department create(@Valid @RequestBody Request r){var e=repo.save(new Department(r.code(), r.name(), r.specialty(), r.location()));audit.record("CREATE","Department",e.getId().toString(),"created");return e;} @GetMapping public List<Department> list(){return repo.findAll();} @GetMapping("/{id}") public Department get(@PathVariable UUID id){return repo.findById(id).orElseThrow(()->new NotFoundException("Department not found: "+id));} @DeleteMapping("/{id}") public void delete(@PathVariable UUID id){if(!repo.existsById(id))throw new NotFoundException("Department not found: "+id);repo.deleteById(id);audit.record("DELETE","Department",id.toString(),"deleted");} }
